def normalize_vocab_query(value):
    value = (value or "").strip().lower()
    value = value.replace("’", "'")
    value_no_accents = (
        value.replace("é", "e").replace("è", "e").replace("ê", "e")
        .replace("à", "a").replace("ù", "u").replace("ô", "o").replace("œ", "oe")
    )

    if value in VOCABULARY_GLOSSARY:
        return value
    if value in VOCABULARY_ALIASES:
        return VOCABULARY_ALIASES[value]
    if value_no_accents in VOCABULARY_ALIASES:
        return VOCABULARY_ALIASES[value_no_accents]

    for key in VOCABULARY_GLOSSARY:
        simple_key = (
            key.replace("é", "e").replace("è", "e").replace("ê", "e")
            .replace("à", "a").replace("ù", "u").replace("ô", "o").replace("œ", "oe")
        )
        if value_no_accents == simple_key:
            return key

    return None


def register_help_document(student_state, doc_id):
    if doc_id not in HELP_DOCUMENTS:
        return False

    used = student_state.setdefault("help_docs_used", [])
    used_ids = {
        item.get("id") if isinstance(item, dict) else item
        for item in used
    }

    # Un document déjà consulté ne peut pas être rouvert pendant la suite.
    if doc_id in used_ids:
        return False

    used.append({
        "id": doc_id,
        "title": HELP_DOCUMENTS[doc_id]["title"],
    })
    student_state["active_help_doc"] = doc_id
    return True


