def normalize_assessment(data, student_state=None):
    result = {
        "competences": [],
        "appreciation": str(data.get("appreciation", "")).strip(),
    }

    student_state = student_state or {}
    returned = data.get("competences", [])
    by_name = {}

    vocab_used = student_state.get("vocab_help_used", []) or []
    docs_used = student_state.get("help_docs_used", []) or []
    activities_used = student_state.get("help_activities_used", []) or []
    media_used = student_state.get("help_media_used", []) or []
    direct_answers = set(student_state.get("direct_answers_given", []) or [])

    doc_ids = {
        item.get("id") if isinstance(item, dict) else item
        for item in docs_used
    }
    activity_ids = {
        item.get("id") for item in activities_used
        if isinstance(item, dict)
    }
    media_ids = {
        item.get("id") for item in media_used
        if isinstance(item, dict)
    }

    def clamp(value, default=1):
        try:
            value = int(value)
        except Exception:
            value = default
        return min(4, max(1, value))

    def composite_cap(name, subparts, base_autonomy):
        values = [
            clamp(part.get("autonomie", base_autonomy), base_autonomy)
            for part in subparts
            if isinstance(part, dict)
        ]
        cap = base_autonomy

        if name == "Identifier la réaction inflammatoire et ses quatre signes":
            # Les documents utilisés ensuite pour EXPLIQUER les mécanismes
            # ne pénalisent jamais cette compétence d'identification.
            return cap

        if name == "Expliquer les manifestations de la réaction inflammatoire":
            if {
                "INFLAM_PAGE2_ROUGEUR",
                "INFLAM_THERMOGRAPHIE",
                "INFLAM_PAGE2_GONFLEMENT",
                "INFLAM_PAGE2_DOULEUR",
            } & doc_ids:
                cap = min(cap, 2)
            if {"ROUGEUR", "CHALEUR", "GONFLEMENT", "DOULEUR"} & direct_answers:
                cap = min(cap, 1)
            elif sum(v <= 2 for v in values) >= 2:
                cap = min(cap, 2)

        elif name == "Expliquer le rôle des cellules sentinelles et des médiateurs chimiques":
            if {
                "INFLAM_CELLULES_SENTINELLES",
                "INFLAM_TABLEAU_MEDIATEURS",
            } & doc_ids:
                cap = min(cap, 2)
            if "SENTINELLES" in direct_answers:
                cap = min(cap, 1)

        elif name == "Expliquer le rôle des leucocytes dans la défense de l'organisme":
            # L'indice étymologique pour retrouver le nom ne doit pas faire croire
            # qu'un recrutement non questionné a été évalué.
            if "LEUCOCYTES_NOM" in direct_answers:
                cap = min(cap, 2)
            elif values and any(v <= 2 for v in values):
                cap = min(cap, 2)

        elif name == "Expliquer les étapes de la phagocytose":
            if (
                "PHAGO_ORDER" in activity_ids
                or "PHAGO_ANNOTATION" in doc_ids
                or "PHAGO_VIDEO" in media_ids
            ):
                cap = min(cap, 2)
            if "PHAGO_NOM" in direct_answers:
                cap = min(cap, 2)

        elif name == "Comprendre et utiliser le vocabulaire scientifique dans une communication écrite adaptée":
            # Le lexique est un indice, mais cette compétence inclut aussi
            # qualité du français, clarté et adaptation au rôle du médecin.
            if len(vocab_used) >= 3:
                cap = min(cap, 2)
            elif len(vocab_used) >= 1:
                cap = min(cap, 3)

        return cap

    for item in returned:
        if not isinstance(item, dict):
            continue

        name = str(item.get("nom", "")).strip()
        if name not in COMPETENCY_NAMES:
            continue

        content_level = clamp(item.get("niveau_contenu", item.get("niveau", 1)))
        autonomy_level = clamp(item.get("autonomie", content_level), content_level)

        subparts = item.get("sous_parties", [])
        if not isinstance(subparts, list):
            subparts = []

        autonomy_level = composite_cap(name, subparts, autonomy_level)
        level = min(content_level, autonomy_level)

        justification = str(item.get("justification", "")).strip()
        if not justification:
            justification = "Évaluation générée à partir des productions de l'élève."

        by_name[name] = {
            "nom": name,
            "niveau": level,
            "niveau_contenu": content_level,
            "autonomie": autonomy_level,
            "sous_parties": subparts,
            "justification": justification,
        }

    for expected_name in COMPETENCY_NAMES:
        item = by_name.get(expected_name)

        if item is None:
            # IMPORTANT : une erreur technique ne devient jamais une maîtrise insuffisante.
            item = {
                "nom": expected_name,
                "niveau": 0,
                "niveau_contenu": 0,
                "autonomie": 0,
                "sous_parties": [],
                "justification": (
                    "Non évalué : l'évaluation automatique n'a pas produit "
                    "de résultat exploitable pour cette compétence."
                ),
            }

        result["competences"].append(item)

    if not result["appreciation"]:
        result["appreciation"] = (
            "Le bilan met en évidence les acquis et les points à consolider au cours de la téléconsultation."
        )

    return result

def generate_assessment(history, student_state):
    dialogue_text = build_dialogue_text(history)
    student_only_text = build_student_only_text(history)

    vocab_used = (student_state or {}).get("vocab_help_used", []) or []
    docs_used = (student_state or {}).get("help_docs_used", []) or []

    activities_used = (student_state or {}).get("help_activities_used", []) or []
    media_used = (student_state or {}).get("help_media_used", []) or []
    direct_answers = (student_state or {}).get("direct_answers_given", []) or []

    aid_trace = (
        "TRACE DES AIDES OUTILS :\n"
        f"- Mots consultés dans le lexique : {', '.join(vocab_used) if vocab_used else 'aucun'}\n"
        f"- Documents de classe consultés : "
        f"{', '.join(item.get('title', item.get('id', '')) if isinstance(item, dict) else str(item) for item in docs_used) if docs_used else 'aucun'}\n"
        f"- Activités de remédiation : "
        f"{', '.join(item.get('title', item.get('id', '')) if isinstance(item, dict) else str(item) for item in activities_used) if activities_used else 'aucune'}\n"
        f"- Supports vidéo : "
        f"{', '.join(item.get('title', item.get('id', '')) if isinstance(item, dict) else str(item) for item in media_used) if media_used else 'aucun'}\n"
        f"- Réponses données directement par M. Dujardin en dernier recours : "
        f"{', '.join(direct_answers) if direct_answers else 'aucune'}\n"
    )

    raw = call_openai(
        [
            {"role": "system", "content": ASSESSMENT_SYSTEM_PROMPT},
            {
                "role": "user",
                "content": (
                    "SOURCE PRINCIPALE POUR NOTER : PRODUCTIONS DE L'ÉLÈVE UNIQUEMENT.\n"
                    "Attribue les acquis uniquement à partir de cette partie :\n\n"
                    f"{student_only_text}\n\n"
                    "CONTEXTE SECONDAIRE : DIALOGUE COMPLET.\n"
                    "Utilise cette partie pour mesurer précisément les relances, indices et le guidage de M. Dujardin.\n"
                    "Pour chaque compétence, repère si l'élève répond spontanément, après une petite relance, "
                    "après plusieurs indices, ou grâce à un guidage étape par étape.\n"
                    "N'attribue jamais à l'élève une information formulée uniquement par M. Dujardin.\n"
                    "IMPORTANT : si une compétence est reconstruite pas à pas par plusieurs questions de M. Dujardin, "
                    "l'autonomie vaut 2 au maximum, même si les réponses finales sont toutes correctes.\n"
                    "Une consultation d'un document de classe est une aide importante : elle ne permet pas un niveau d'autonomie supérieur à 2 "
                    "pour la compétence concernée.\n"
                    "Une ou deux consultations ponctuelles du lexique peuvent rester compatibles avec le niveau 3 de vocabulaire ; "
                    "plusieurs consultations indiquent une fragilité.\n\n"
                    f"{aid_trace}\n"
                    f"{dialogue_text}"
                ),
            },
        ],
        temperature=0.0,
    )

    cleaned = raw.strip()

    if cleaned.startswith("```"):
        cleaned = cleaned.strip("`")
        if cleaned.lower().startswith("json"):
            cleaned = cleaned[4:].strip()

    try:
        data = json.loads(cleaned)
    except Exception:
        raise RuntimeError(
            "L'évaluation automatique n'a pas renvoyé un JSON valide. "
            "Relance la génération du bilan."
        )

    return normalize_assessment(data, student_state)

# ============================================================
# RAPPORT TEXTE
# ============================================================

def build_report_text(student_state, history, assessment):
    first_names = (student_state or {}).get("first_names") or "élève"
    classe = (student_state or {}).get("class") or "classe"
    restart_count = int((student_state or {}).get("restart_count", 0))

    lines = []

    lines.append("1. Identité")
    lines.append(f"- Prénoms : {first_names}")
    lines.append(f"- Classe : {classe}")
    lines.append(f"- Nombre de recommencements : {restart_count}")
    lines.append("")

    lines.append("2. Dialogue complet de la téléconsultation")
    dialogue = get_consultation_dialogue(history)

    for msg in dialogue:
        speaker = "Élève (médecin)" if msg["role"] == "user" else "M. Dujardin"
        lines.append(f"{speaker} : {msg['content']}")
        lines.append("")

    lines.append("3. Aides utilisées pendant la téléconsultation")
    vocab_used = (student_state or {}).get("vocab_help_used", []) or []
    docs_used = (student_state or {}).get("help_docs_used", []) or []
    activities_used = (student_state or {}).get("help_activities_used", []) or []
    media_used = (student_state or {}).get("help_media_used", []) or []

    if vocab_used:
        lines.append("Aide vocabulaire : " + ", ".join(vocab_used))
    else:
        lines.append("Aide vocabulaire : aucune")

    if docs_used:
        lines.append("Documents de classe consultés :")
        for item in docs_used:
            if isinstance(item, dict):
                lines.append(f"- {item.get('title', item.get('id', 'Document'))}")
            else:
                lines.append(f"- {item}")
    else:
        lines.append("Documents de classe consultés : aucun")

    if activities_used:
        lines.append("Activités de remédiation utilisées :")
        for item in activities_used:
            if isinstance(item, dict):
                attempts = int(item.get("attempts", 0))
                lines.append(
                    f"- {item.get('title', item.get('id', 'Activité'))} "
                    f"(tentative(s) : {attempts})"
                )

    if media_used:
        lines.append("Supports vidéo consultés :")
        for item in media_used:
            if isinstance(item, dict):
                lines.append(f"- {item.get('title', item.get('id', 'Vidéo'))}")

    lines.append("")
    lines.append("4. Ce qu’il faut retenir – correction scientifique")

    for title, explanation in SCIENTIFIC_CORRECTIONS:
        lines.append(f"{title} : {explanation}")
        lines.append("")

    lines.append("5. Bilan pédagogique par compétences")

    for comp in assessment["competences"]:
        level = comp["niveau"]
        lines.append(f"- {comp['nom']} : {LEVEL_LABELS[level]}")
        if level == 0:
            lines.append("  Cette compétence n'a pas été notée à cause d'un problème technique d'évaluation.")
        if "autonomie" in comp and int(comp.get("autonomie", 0)) > 0:
            lines.append(
                f"  Autonomie observée : niveau {comp['autonomie']} / 4"
            )
        lines.append(f"  Justification : {comp['justification']}")

    lines.append("")
    lines.append("6. Appréciation")
    lines.append(assessment["appreciation"])
    lines.append("")
    lines.append("7. Pour progresser")

    fragile = [
        comp for comp in assessment["competences"]
        if int(comp.get("niveau", 0)) in (1, 2)
    ]

    if fragile:
        lines.append("Après la remédiation en classe, revois en priorité :")
        for comp in fragile:
            lines.append(f"- {comp['nom']}")
    else:
        lines.append(
            "Les connaissances essentielles sont globalement acquises. "
            "Relis la partie « Ce qu’il faut retenir » après la correction en classe."
        )

    if vocab_used:
        lines.append("- Vocabulaire à revoir : " + ", ".join(vocab_used))

    if docs_used:
        lines.append("- Reprendre les extraits de documents de classe consultés pendant la téléconsultation.")

    return "\n".join(lines)

# ============================================================
# PDF
# ============================================================

def pdf_safe_text(text):
    replacements = {
        "\u2019": "'",
        "\u2018": "'",
        "\u201c": '"',
        "\u201d": '"',
        "\u2022": "-",
        "\u2013": "-",
        "\u2014": "-",
        "\u00a0": " ",
    }

    for old, new in replacements.items():
        text = text.replace(old, new)

    return text


def build_report_pdf(student_state, history, assessment):
    buffer = BytesIO()

    doc = SimpleDocTemplate(
        buffer,
        pagesize=A4,
        rightMargin=1.4 * cm,
        leftMargin=1.4 * cm,
        topMargin=1.4 * cm,
        bottomMargin=1.4 * cm,
        title="Bilan de téléconsultation SVT - M. Dujardin",
        author="Chatbot pédagogique SVT",
    )

    styles = getSampleStyleSheet()

    title_style = ParagraphStyle(
        "DujardinTitle",
        parent=styles["Title"],
        fontName="Helvetica-Bold",
        fontSize=15,
        leading=18,
        alignment=TA_CENTER,
        spaceAfter=10,
    )

    heading_style = ParagraphStyle(
        "DujardinHeading",
        parent=styles["Heading2"],
        fontName="Helvetica-Bold",
        fontSize=11.5,
        leading=14,
        spaceBefore=8,
        spaceAfter=5,
    )

    body_style = ParagraphStyle(
        "DujardinBody",
        parent=styles["BodyText"],
        fontName="Helvetica",
        fontSize=9,
        leading=12,
        spaceAfter=4,
    )

    small_style = ParagraphStyle(
        "DujardinSmall",
        parent=body_style,
        fontSize=8,
        leading=10,
    )

    story = [
        Paragraph("Bilan de téléconsultation SVT - M. Dujardin", title_style),
    ]

    first_names = (student_state or {}).get("first_names") or "élève"
    classe = (student_state or {}).get("class") or "classe"
    restart_count = int((student_state or {}).get("restart_count", 0))

    story.append(Paragraph("1. Identité", heading_style))
    story.append(
        Paragraph(
            f"<b>Prénoms :</b> {escape(pdf_safe_text(first_names))}",
            body_style,
        )
    )
    story.append(
        Paragraph(
            f"<b>Classe :</b> {escape(pdf_safe_text(classe))}",
            body_style,
        )
    )
    story.append(
        Paragraph(
            f"<b>Nombre de recommencements :</b> {restart_count}",
            body_style,
        )
    )

    story.append(
        Paragraph("2. Dialogue complet de la téléconsultation", heading_style)
    )

    for msg in get_consultation_dialogue(history):
        speaker = "Élève (médecin)" if msg["role"] == "user" else "M. Dujardin"
        content = escape(pdf_safe_text(msg["content"])).replace("\n", "<br/>")

        story.append(
            Paragraph(
                f"<b>{escape(speaker)} :</b> {content}",
                body_style,
            )
        )

    story.append(
        Paragraph("3. Aides utilisées pendant la téléconsultation", heading_style)
    )

    vocab_used = (student_state or {}).get("vocab_help_used", []) or []
    docs_used = (student_state or {}).get("help_docs_used", []) or []
    activities_used = (student_state or {}).get("help_activities_used", []) or []
    media_used = (student_state or {}).get("help_media_used", []) or []

    story.append(
        Paragraph(
            "<b>Aide vocabulaire :</b> "
            + escape(pdf_safe_text(", ".join(vocab_used) if vocab_used else "aucune")),
            body_style,
        )
    )

    if docs_used:
        story.append(Paragraph("<b>Documents de classe consultés :</b>", body_style))
        for item in docs_used:
            title = item.get("title", item.get("id", "Document")) if isinstance(item, dict) else str(item)
            story.append(Paragraph("- " + escape(pdf_safe_text(title)), body_style))
    else:
        story.append(Paragraph("<b>Documents de classe consultés :</b> aucun", body_style))

    if activities_used:
        story.append(Paragraph("<b>Activités de remédiation utilisées :</b>", body_style))
        for item in activities_used:
            if isinstance(item, dict):
                attempts = int(item.get("attempts", 0))
                title = item.get("title", item.get("id", "Activité"))
                story.append(
                    Paragraph(
                        f"- {escape(pdf_safe_text(title))} (tentative(s) : {attempts})",
                        body_style,
                    )
                )

    if media_used:
        story.append(Paragraph("<b>Supports vidéo consultés :</b>", body_style))
        for item in media_used:
            if isinstance(item, dict):
                title = item.get("title", item.get("id", "Vidéo"))
                story.append(
                    Paragraph("- " + escape(pdf_safe_text(title)), body_style)
                )

    story.append(
        Paragraph("4. Ce qu’il faut retenir – correction scientifique", heading_style)
    )

    for title, explanation in SCIENTIFIC_CORRECTIONS:
        story.append(
            Paragraph(
                f"<b>{escape(title)} :</b> {escape(pdf_safe_text(explanation))}",
                body_style,
            )
        )

    story.append(
        Paragraph("5. Bilan pédagogique par compétences", heading_style)
    )

    table_data = [
        [
            Paragraph("<b>Compétence évaluée</b>", small_style),
            Paragraph("<b>Niveau</b>", small_style),
            Paragraph("<b>Justification</b>", small_style),
        ]
    ]

    level_backgrounds = {
        0: colors.HexColor("#EEEEEE"),  # non évalué
        1: colors.HexColor("#FDE2E2"),  # rouge
        2: colors.HexColor("#FFF4BF"),  # jaune
        3: colors.HexColor("#E1ECFA"),  # bleu
        4: colors.HexColor("#E2F5E9"),  # vert
    }

    row_levels = []

    for comp in assessment["competences"]:
        level = int(comp["niveau"])
        row_levels.append(level)

        if level == 0:
            level_text = "Problème technique"
        else:
            level_text = LEVEL_LABELS[level].split("–", 1)[1].strip()

        table_data.append(
            [
                Paragraph(
                    escape(pdf_safe_text(comp["nom"])),
                    small_style,
                ),
                Paragraph(
                    (
                        f"<b>Non évalué</b><br/>{escape(level_text)}"
                        if level == 0
                        else f"<b>Niveau {level}</b><br/>{escape(level_text)}"
                    ),
                    small_style,
                ),
                Paragraph(
                    escape(pdf_safe_text(comp["justification"])),
                    small_style,
                ),
            ]
        )

    table = Table(
        table_data,
        colWidths=[6.2 * cm, 3.2 * cm, 8.0 * cm],
        repeatRows=1,
        hAlign="LEFT",
    )

    commands = [
        ("BACKGROUND", (0, 0), (-1, 0), colors.HexColor("#EDEDED")),
        ("GRID", (0, 0), (-1, -1), 0.4, colors.HexColor("#999999")),
        ("VALIGN", (0, 0), (-1, -1), "TOP"),
        ("LEFTPADDING", (0, 0), (-1, -1), 5),
        ("RIGHTPADDING", (0, 0), (-1, -1), 5),
        ("TOPPADDING", (0, 0), (-1, -1), 4),
        ("BOTTOMPADDING", (0, 0), (-1, -1), 4),
    ]

    for row_index, level in enumerate(row_levels, start=1):
        commands.append(
            (
                "BACKGROUND",
                (1, row_index),
                (1, row_index),
                level_backgrounds[level],
            )
        )

    table.setStyle(TableStyle(commands))
    story.append(table)
    story.append(Spacer(1, 8))

    story.append(Paragraph("<b>Repères des niveaux :</b>", body_style))
    story.append(
        Paragraph(
            "<b>Niveau 1 – Maîtrise insuffisante :</b> bases non assimilées, objectifs non atteints.",
            small_style,
        )
    )
    story.append(
        Paragraph(
            "<b>Niveau 2 – Maîtrise fragile :</b> bases partiellement comprises, besoin d'un étayage important.",
            small_style,
        )
    )
    story.append(
        Paragraph(
            "<b>Niveau 3 – Maîtrise satisfaisante :</b> compétence acquise de manière autonome, niveau attendu.",
            small_style,
        )
    )
    story.append(
        Paragraph(
            "<b>Niveau 4 – Très bonne maîtrise :</b> maîtrise très solide, précise et mobilisée avec aisance.",
            small_style,
        )
    )

    story.append(Paragraph("6. Appréciation", heading_style))
    story.append(
        Paragraph(
            escape(pdf_safe_text(assessment["appreciation"])),
            body_style,
        )
    )

    story.append(Paragraph("7. Pour progresser", heading_style))
    fragile = [
        comp for comp in assessment["competences"]
        if int(comp.get("niveau", 1)) <= 2
    ]

    if fragile:
        story.append(
            Paragraph(
                "Après la remédiation en classe, revois en priorité :",
                body_style,
            )
        )
        for comp in fragile:
            story.append(
                Paragraph(
                    f"- {escape(pdf_safe_text(comp['nom']))}",
                    body_style,
                )
            )
    else:
        story.append(
            Paragraph(
                "Les connaissances essentielles sont globalement acquises. "
                "Relis la partie « Ce qu'il faut retenir » après la correction en classe.",
                body_style,
            )
        )

    if vocab_used:
        story.append(
            Paragraph(
                "<b>Vocabulaire à revoir :</b> "
                + escape(pdf_safe_text(", ".join(vocab_used))),
                body_style,
            )
        )

    if docs_used:
        story.append(
            Paragraph(
                "Reprendre les extraits de documents de classe consultés pendant la téléconsultation.",
                body_style,
            )
        )

    doc.build(story)
    buffer.seek(0)
    return buffer.getvalue()

