def autofocus_response_input():
    components.html(
        """
        <script>
        setTimeout(() => {
            const doc = window.parent.document;
            const target = Array.from(doc.querySelectorAll('input')).find(
                el => (el.getAttribute('placeholder') || '').includes('Écrivez votre réponse ici')
            );
            if (target) target.focus();
        }, 180);
        </script>
        """,
        height=0,
        width=0,
    )


# ============================================================
# ÉTAT STREAMLIT
# ============================================================

def make_initial_student_state(restart_count=0):
    return {
        "step": "ask_first_names",
        "first_names": None,
        "class": None,
        "finished": False,
        "restart_count": restart_count,
        "vocab_help_used": [],
        "help_docs_used": [],
        "help_activities_used": [],
        "help_media_used": [],
        "active_help_doc": None,
        "active_help_activity": None,
        "active_help_video": None,
        "current_topic": None,
        "topic_blockages": {},
        "direct_answers_given": [],
    }


def reset_state(message=None, keep_restart_count=False):
    previous_count = 0

    if keep_restart_count and "student_state" in st.session_state:
        previous_count = int(
            st.session_state.student_state.get("restart_count", 0)
        )

    st.session_state.history = [
        {
            "role": "assistant",
            "content": message or "Bonjour ! Quel est votre prénom / Quels sont vos prénoms ?",
        }
    ]

    st.session_state.student_state = make_initial_student_state(previous_count)
    st.session_state.image_visible = False
    st.session_state.report_text = None
    st.session_state.report_pdf = None
    st.session_state.assessment = None
    st.session_state.report_code = None
    st.session_state.save_code = None


if "history" not in st.session_state:
    reset_state()


def restart_consultation():
    """Recommence depuis le début en conservant le code de sauvegarde actif."""
    current_count = int(
        st.session_state.student_state.get("restart_count", 0)
    ) + 1
    active_code = st.session_state.get("save_code")

    st.session_state.history = [
        {
            "role": "assistant",
            "content": (
                "Consultation recommencée depuis le début. "
                "Bonjour ! Quel est votre prénom / Quels sont vos prénoms ?"
            ),
        }
    ]
    st.session_state.student_state = make_initial_student_state(current_count)
    st.session_state.image_visible = False
    st.session_state.report_text = None
    st.session_state.report_pdf = None
    st.session_state.assessment = None
    st.session_state.report_code = None
    st.session_state.save_code = active_code
    st.session_state.restart_confirm = False

    autosave_current_session()


# ============================================================
# LOGIQUE DU CHAT
# ============================================================

def process_user_message(text):
    text = (text or "").strip()

    if not text:
        return

    upper = text.upper()
    history = st.session_state.history
    student_state = st.session_state.student_state

    # ---------- RECOMMENCER ----------
    # Compatibilité avec l'ancienne commande texte.
    if upper == "RECOMMENCER":
        restart_consultation()
        return

    # ---------- REPRISE ----------
    if upper.startswith("REPRISE"):
        parts = text.split()

        if len(parts) < 2:
            history.append({"role": "user", "content": text})
            history.append(
                {
                    "role": "assistant",
                    "content": (
                        "Pour reprendre une consultation, écris par exemple : "
                        "REPRISE ABC123."
                    ),
                }
            )
            return

        # Accepte les deux formes :
        # REPRISE ABC123
        # REPRISE CODE ABC123
        if len(parts) >= 3 and parts[1].strip().upper() == "CODE":
            code = parts[2].strip().upper()
        else:
            code = parts[1].strip().upper()
        data = load_session(code)

        if data is None:
            history.append({"role": "user", "content": text})
            history.append(
                {
                    "role": "assistant",
                    "content": (
                        "Je ne trouve pas ce code de sauvegarde. "
                        "Vérifie le code. Si le problème persiste, demande de l'aide à ton professeur."
                    ),
                }
            )
            return

        st.session_state.history = data.get(
            "history",
            [
                {
                    "role": "assistant",
                    "content": "Bonjour ! Quel est votre prénom / Quels sont vos prénoms ?",
                }
            ],
        )

        loaded_state = data.get("student_state") or make_initial_student_state()

        if "name" in loaded_state and "first_names" not in loaded_state:
            loaded_state["first_names"] = loaded_state.pop("name")

        loaded_state.setdefault("restart_count", 0)
        loaded_state.setdefault("finished", False)
        loaded_state.setdefault("vocab_help_used", [])
        loaded_state.setdefault("help_docs_used", [])
        loaded_state.setdefault("help_activities_used", [])
        loaded_state.setdefault("help_media_used", [])
        loaded_state.setdefault("active_help_doc", None)
        loaded_state.setdefault("active_help_activity", None)
        loaded_state.setdefault("active_help_video", None)
        loaded_state.setdefault("current_topic", None)
        loaded_state.setdefault("topic_blockages", {})
        loaded_state.setdefault("direct_answers_given", [])

        st.session_state.student_state = loaded_state
        st.session_state.image_visible = data.get("image_visible", False)
        st.session_state.report_text = None
        st.session_state.report_pdf = None
        st.session_state.assessment = None
        st.session_state.save_code = code

        st.session_state.history.append(
            {
                "role": "assistant",
                "content": (
                    f"Consultation reprise avec le code {code}. "
                    "Tu peux continuer là où tu t'étais arrêté."
                ),
            }
        )
        return

    # ---------- SAUVEGARDE ----------
    if upper == "SAUVEGARDE":
        code = st.session_state.get("save_code")

        if not code:
            code = uuid.uuid4().hex[:6].upper()

        ok, error = save_session(
            code,
            history,
            student_state,
            st.session_state.image_visible,
        )

        history.append({"role": "user", "content": text})

        if not ok:
            history.append(
                {
                    "role": "assistant",
                    "content": (
                        "La sauvegarde n'a pas pu être créée pour le moment. "
                        f"{error}"
                    ),
                }
            )
            return

        st.session_state.save_code = code

        history.append(
            {
                "role": "assistant",
                "content": (
                    f"La consultation est sauvegardée. Ton code est : {code}\n\n"
                    f"Pour la reprendre à la prochaine séance, écris : REPRISE {code}\n\n"
                    "Cette sauvegarde sera mise à jour automatiquement pendant la suite de la consultation."
                ),
            }
        )
        return

    step = student_state.get("step", "ask_first_names")

    # ---------- PRÉNOMS ----------
    if step == "ask_first_names":
        student_state["first_names"] = text

        history.append(
            {
                "role": "user",
                "content": text,
            }
        )

        history.append(
            {
                "role": "assistant",
                "content": "Merci ! Et dans quelle classe êtes-vous ? (ex : 3A, 3E...)",
            }
        )

        student_state["step"] = "ask_class"
        autosave_current_session()
        return

    # ---------- CLASSE ----------
    if step == "ask_class":
        student_state["class"] = text

        history.append(
            {
                "role": "user",
                "content": text,
            }
        )

        history.append(
            {
                "role": "assistant",
                "content": (
                    f"Merci {student_state['first_names']} de la {student_state['class']}. "
                    "Nous pouvons commencer la consultation."
                ),
            }
        )

        history.append(
            {
                "role": "assistant",
                "content": INTRO_MESSAGE,
            }
        )

        student_state["step"] = "consultation"
        student_state["current_topic"] = "IDENTIFICATION"
        student_state["topic_blockages"] = {}
        st.session_state.image_visible = True

        autosave_current_session()
        return

    # ---------- CONSULTATION ----------
    # Les supports restent visibles pendant toute une séquence de remédiation.
    # Ils ne sont fermés que lorsque l'élève produit une vraie tentative
    # (et non un nouveau « je ne sais pas »).
    history.append({"role": "user", "content": text})
    current_topic = student_state.get("current_topic")
    normalized = text.lower()

    if current_topic == "LEUCOCYTES_NOM" and ("leucocyte" in normalized or "globule blanc" in normalized):
        student_state["current_topic"] = "LEUCOCYTES_ROLE"
        student_state.setdefault("topic_blockages", {})["LEUCOCYTES_ROLE"] = 0
        history.append({"role": "assistant", "content": "Exactement docteur, ce sont les leucocytes. Quel rôle jouent-ils dans la zone blessée ou infectée ?"})
        autosave_current_session()
        return

    if current_topic == "PHAGO_NOM" and "phagocytose" in normalized:
        student_state["current_topic"] = "PHAGO_NOMBRE"
        student_state.setdefault("topic_blockages", {})["PHAGO_NOMBRE"] = 0
        history.append({"role": "assistant", "content": "Oui, c'est bien la phagocytose. Combien de grandes étapes comporte ce mécanisme, docteur ?"})
        autosave_current_session()
        return

    if current_topic == "PHAGO_NOMBRE" and re.search(r"\b(4|quatre)\b", normalized):
        student_state["current_topic"] = "PHAGO_ETAPES"
        student_state.setdefault("topic_blockages", {})["PHAGO_ETAPES"] = 0
        history.append({"role": "assistant", "content": "D'accord docteur, il y en a donc quatre. Comment s'appellent ces quatre étapes et dans quel ordre se déroulent-elles ?"})
        autosave_current_session()
        return

    if is_blocking_response(text) and current_topic:
        blockages = student_state.setdefault("topic_blockages", {})
        blockages[current_topic] = int(blockages.get(current_topic, 0)) + 1
        count = blockages[current_topic]

        if count == 1 and current_topic in FIRST_BLOCKAGE_REPLIES:
            history.append({"role": "assistant", "content": FIRST_BLOCKAGE_REPLIES[current_topic]})
            autosave_current_session()
            return

        if current_topic in TOPIC_HELP_SEQUENCE and count == 2:
            sequence = TOPIC_HELP_SEQUENCE[current_topic]
            if sequence and register_help_document(student_state, sequence[0]):
                history.append({"role": "assistant", "content": "Je vois que cette partie reste difficile. Je vous redonne temporairement le document étudié en classe. Cherchez vous-même l'information utile, puis expliquez-la avec vos propres mots."})
                autosave_current_session()
                return

        if current_topic in TOPIC_HELP_SEQUENCE and count == 3:
            sequence = TOPIC_HELP_SEQUENCE[current_topic]
            if len(sequence) >= 2 and register_help_document(student_state, sequence[1]):
                history.append({"role": "assistant", "content": "Je vous donne maintenant un second support plus ciblé. Utilisez-le pour construire votre propre réponse."})
                autosave_current_session()
                return
            focused = POST_DOCUMENT_REPLIES.get(current_topic)
            if focused:
                history.append({"role": "assistant", "content": focused})
                autosave_current_session()
                return

        if current_topic in {"ROUGEUR","CHALEUR","GONFLEMENT","DOULEUR","SENTINELLES"} and count >= 4:
            fallback = {
                "ROUGEUR": "Les vaisseaux sanguins se dilatent, ce qui augmente l'afflux de sang et provoque la rougeur.",
                "CHALEUR": "L'afflux de sang plus chaud que les tissus augmente la température locale.",
                "GONFLEMENT": "Une partie du plasma sort des capillaires et s'accumule dans les tissus, ce qui provoque le gonflement.",
                "DOULEUR": "La douleur vient notamment de la pression liée au gonflement et de substances chimiques qui stimulent les récepteurs de la douleur.",
                "SENTINELLES": "Les cellules sentinelles détectent les microbes puis libèrent des médiateurs chimiques participant au déclenchement de l'inflammation.",
            }[current_topic]
            student_state.setdefault("direct_answers_given", []).append(current_topic)
            history.append({"role": "assistant", "content": "La réponse attendue est la suivante : " + fallback + " Reformulez maintenant cette idée avec vos propres mots, docteur."})
            autosave_current_session()
            return

        if current_topic == "LEUCOCYTES_NOM" and count >= 2:
            student_state.setdefault("direct_answers_given", []).append("LEUCOCYTES_NOM")
            student_state["current_topic"] = "LEUCOCYTES_ROLE"
            student_state.setdefault("topic_blockages", {})["LEUCOCYTES_ROLE"] = 0
            history.append({"role": "assistant", "content": "Ces cellules s'appellent les leucocytes. Quel rôle jouent-elles dans la zone blessée ou infectée, docteur ?"})
            autosave_current_session()
            return

        if current_topic == "PHAGO_NOM" and count >= 2:
            student_state.setdefault("direct_answers_given", []).append("PHAGO_NOM")
            student_state["current_topic"] = "PHAGO_NOMBRE"
            student_state.setdefault("topic_blockages", {})["PHAGO_NOMBRE"] = 0
            history.append({"role": "assistant", "content": "Le mécanisme s'appelle la phagocytose. Combien de grandes étapes comporte-t-il, docteur ?"})
            autosave_current_session()
            return

        if current_topic == "PHAGO_NOMBRE" and count >= 1:
            student_state["current_topic"] = "PHAGO_ETAPES"
            student_state.setdefault("topic_blockages", {})["PHAGO_ETAPES"] = 0
            history.append({"role": "assistant", "content": "Ce n'est pas grave si le nombre ne vous revient pas tout de suite. Quelles étapes vous rappelez-vous, docteur, et dans quel ordre se déroulent-elles ?"})
            autosave_current_session()
            return

        if current_topic == "PHAGO_ETAPES" and count >= 1:
            register_help_activity(student_state, "PHAGO_ORDER", "Activité de remise en ordre des étapes de la phagocytose")
            history.append({"role": "assistant", "content": "Je vous propose de reprendre la manipulation vue en classe. Associez les images A, B, C et D aux étapes et reconstituez leur ordre."})
            autosave_current_session()
            return

        if current_topic == "PHAGO_EXPLICATION" and count >= 1:
            added_doc = False
            if "PHAGO_ANNOTATION" not in used_help_ids(student_state):
                added_doc = register_help_document(student_state, "PHAGO_ANNOTATION")
            already_video = any(isinstance(item, dict) and item.get("id") == "PHAGO_VIDEO" for item in student_state.get("help_media_used", []))
            if not already_video:
                register_help_video(student_state)
            if added_doc or not already_video:
                history.append({"role": "assistant", "content": "Pour vous aider à expliquer le mécanisme, je vous redonne ensemble le document annoté et l'animation travaillés en classe. Observez-les puis expliquez la phagocytose avec vos propres mots."})
                autosave_current_session()
                return

    # Une réponse exploitable ferme maintenant les supports temporaires.
    # Les « je ne sais pas » sont déjà sortis plus haut et conservent donc le document.
    if student_state.get("active_help_doc"):
        student_state["active_help_doc"] = None
    if student_state.get("active_help_video"):
        student_state["active_help_video"] = None

    used_doc_ids = {
        item.get("id") if isinstance(item, dict) else item
        for item in student_state.get("help_docs_used", [])
    }

    current_topic = student_state.get("current_topic")
    current_blockages = int(
        student_state.setdefault("topic_blockages", {}).get(current_topic, 0)
    ) if current_topic else 0

    dynamic_help_context = (
        "\n\nÉTAT PILOTÉ PAR L'APPLICATION : "
        f"thème actuel = {current_topic or 'non défini'} ; "
        f"blocages explicites sur ce thème = {current_blockages}. "
        "Respecte strictement ce thème et ne donne pas une réponse complète "
        "à la place de l'élève. "
        "\nDOCUMENTS DÉJÀ CONSULTÉS ET DONC INTERDITS À ROUVRIR : "
        + (", ".join(sorted(used_doc_ids)) if used_doc_ids else "aucun")
        + "."
    )

    messages = [
        {
            "role": "system",
            "content": SYSTEM_PROMPT + dynamic_help_context,
        }
    ] + history

    try:
        reply = call_openai(
            messages,
            temperature=0.20,
        )
    except Exception as exc:
        reply = f"Erreur lors de l'appel à OpenAI : {exc}"

    (
        reply,
        topic_marker,
        requested_doc_id,
        requested_activity_id,
        requested_video_id,
    ) = strip_support_markers(reply)

    # Garde-fou pédagogique :
    # après l'évaluation du rôle des leucocytes, M. Dujardin doit faire
    # RETROUVER le nom du mécanisme sans prononcer « phagocytose ».
    previous_topic = current_topic
    lower_reply = (reply or "").lower()

    if (
        previous_topic == "LEUCOCYTES_ROLE"
        and (
            "phagocytose" in lower_reply
            or ("comment s'appelle" in lower_reply and "mécanisme" in lower_reply)
            or ("comment appelle" in lower_reply and "mécanisme" in lower_reply)
        )
    ):
        reply = (
            "Certains leucocytes peuvent englober puis détruire les microbes. "
            "Comment appelle-t-on ce mécanisme, docteur ?"
        )
        topic_marker = "PHAGO_NOM"
        requested_doc_id = None
        requested_activity_id = None
        requested_video_id = None

    inferred_topic = infer_topic_from_reply(
        reply,
        student_state.get("current_topic"),
    )

    # Le texte réellement affiché prime sur le marqueur du modèle :
    # cela évite qu'une transition vers la douleur conserve par erreur
    # l'ancien état « gonflement ».
    if inferred_topic:
        student_state["current_topic"] = inferred_topic
    elif topic_marker:
        student_state["current_topic"] = topic_marker

    if requested_doc_id:
        registered = register_help_document(student_state, requested_doc_id)
        if registered:
            autosave_current_session()

    if requested_activity_id == "PHAGO_ORDER":
        register_help_activity(
            student_state,
            "PHAGO_ORDER",
            "Activité de remise en ordre des étapes de la phagocytose",
        )
        autosave_current_session()

    if requested_video_id == "PHAGO_VIDEO":
        register_help_video(student_state)
        autosave_current_session()

    history.append(
        {
            "role": "assistant",
            "content": reply,
        }
    )

    if "merci beaucoup docteur, je vais prendre soin de ma main" in reply.lower():
        student_state["finished"] = True

    autosave_current_session()

# ============================================================
# INTERFACE
# ============================================================

